module priority_encoder (input [7:0] D, output [2:0] EN);
  // EN reflects the three most‑significant inputs
  EN = D[7:5];
endmodule

module mux3to1(
    reset,
    clk,
    sel,
    in0,
    in1,
    in2,
    out);

// Inputs
input reset;
input clk;
input [2:0] sel;
input in0;
input in1;
input in2;

// Outputs
output out;

REG out @clk.pos reset.sync->0 PORT
  sel[2]=0 & sel[1]=0 & sel[0]=0 -> in0
| sel[2]=0 & sel[1]=0 & sel[0]=1 -> in1
| sel[2]=0 & sel[1]=1 & sel[0]=0 -> in2
| * -> 0

endmodule

// This is a Verilog implementation, not VSL.
module dff_sr (
    input  wire D,   // Data input
    input  wire C,   // Clock
    input  wire R,   // Synchronous reset (active high)
    input  wire S,   // Synchronous set   (active high)
    output reg  Q    // Output
);

    // Synchronous set/reset D‑flip‑flop
    // Priority: reset takes precedence over set when both are asserted (undefined behavior otherwise).
    always @(posedge C) begin
        if (R)       Q <= 1'b0;   // synchronous reset
        else if (S) Q <= 1'b1;   // synchronous set
        else        Q <= D;       // normal D‑FF operation
    end

endmodule

module adder_4bit (Cin, A, B, Clk, En, Rst, Sum, Cout);
  // ------------------------------------------------------------
  // 4‑bit ripple‑style adder with synchronous reset and enable.
  // ------------------------------------------------------------
  //  * Inputs  : A[3:0] , B[3:0] , Cin , Clk , En , Rst
  //  * Outputs : Sum[3:0] , Cout (registered outputs)
  //  * Behaviour:
  //      – On the rising edge of Clk the output registers are updated.
  //      – If Rst is high the registers are cleared to 0 (synchronous reset).
  //      – If En is low the registers retain their current content.
  //      – If En is high (and Rst is low) a new addition is performed:
  //            {Cout,Sum} = A + B + Cin.
  // ------------------------------------------------------------

  input  wire        Cin;
  input  wire [3:0]  A, B;
  input  wire        Clk;
  input  wire        En;
  input  wire        Rst;

  output reg [3:0]   Sum;
  output reg         Cout;

  // Sequential logic – synchronous reset, enable‑controlled update
  always @(posedge Clk) begin
    if (Rst) begin
      Sum  <= 4'b0000;
      Cout <= 1'b0;
    end else if (En) begin
      {Cout, Sum} <= A + B + Cin; // full‑adder result, carry‑out in Cout
    end else begin
      // En == 0 → hold previous values (no assignment needed, but kept for clarity)
      Sum  <= Sum;
      Cout <= Cout;
    end
  end

endmodule

module mux_2to1 (
    input  a,
    input  b,
    input  sel,
    output out
);

    // SkyWater 130nm standard cell library
    // (make sure the library file is included in the compilation flow)
    `include "sky130_fd_sc_hd.v"

    // Invert the select signal
    wire sel_n;
    sky130_fd_sc_hd__inv_1 u_inv_sel (
        .A (sel),
        .Y (sel_n)
    );

    // (sel & a)
    wire sel_and_a;
    sky130_fd_sc_hd__and2_1 u_and1 (
        .A (sel),
        .B (a),
        .X (sel_and_a)
    );

    // (~sel & b)
    wire nsel_and_b;
    sky130_fd_sc_hd__and2_1 u_and2 (
        .A (sel_n),
        .B (b),
        .X (nsel_and_b)
    );

    // Combine the two products
    sky130_fd_sc_hd__or2_1 u_or (
        .A (sel_and_a),
        .B (nsel_and_b),
        .X (out)
    );

endmodule

module simple_arith (input1, input2, ctrl, out)
  // input1, input2 : 4‑bit operands
  // ctrl[1:0] : 2‑bit operation selector
  // out       : 4‑bit result

COMB out
  ctrl[1]=0 & ctrl[0]=0 -> ((~(input1 + input2)) + 1) & 4'b1111
| ctrl[1]=0 & ctrl[0]=1 -> (input1 - input2) & 4'b1111
| *                -> 4'b0000
